DO $compendio_0$ BEGIN IF EXISTS(SELECT id,registro_id,conjunto_regras_codigo,fonte_id,nome_pt,nome_original,descricao_pt,descricao_html,revisado_2024,automacao,caminho_fonte,ancora_fonte,hash_fonte FROM jsonb_populate_recordset(NULL::public.compendio_revisoes,'[{"id":"9ba88569-5ca6-8dd5-a8de-b57118ab3f05","registro_id":"4d4ad532-b3c2-85c7-af35-be50071b1303","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Rugido Nemeio","nome_original":"Rugido Nemeio","descricao_pt":"Como Ação Bônus, você libera um rugido. Criaturas à sua escolha a até 3 m fazem um teste de resistência de Sabedoria (CD 8 + Proficiência + Constituição). Em caso de falha, ficam Amedrontadas até o início do seu próximo turno. Usos: 1x por Descanso Longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/17/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"b723ddc6-0527-8af9-a1cc-384edf368294","registro_id":"b2598be5-1599-896b-a70a-a2f813bccbbd","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Instinto Predador","nome_original":"Instinto Predador","descricao_pt":"Quando reduz uma criatura a 0 PV com um ataque corpo a corpo, pode usar sua Reação para se mover até 10 pés sem provocar Ataques de Oportunidade. Usos: 1x descanso curto.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/17/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"4cfc2bf5-ca69-88f0-abab-a249f9d7413d","registro_id":"9d5fabfc-693d-8da8-a35f-84766004708a","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Corpo de Nemeia","nome_original":"Corpo de Nemeia","descricao_pt":"Você pode usar o atributo de Força para testes de Acrobacia, ao invés de Destreza. Além disso, conta como uma categoria de tamanho maior para determinar sua capacidade de carga e o peso que pode empurrar, arrastar ou levantar.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/17/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"15934deb-afb6-8e42-a911-f6d1a6c6fbaf","registro_id":"6657676f-3316-8c04-ae84-499f16260aa1","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Constituição Norlock","nome_original":"Constituição Norlock","descricao_pt":"O valor máximo do seu atributo de Constituição é 23, em vez de 20. Além disso, você possui Vantagem em testes de Força (Atletismo).","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/18/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"41a935e5-1fb5-803e-af10-7896ffa60003","registro_id":"8dfd1990-f6c2-844f-acd3-f7f22769ec8a","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Golpes Poderosos","nome_original":"Golpes Poderosos","descricao_pt":"Quando realiza um Ataque Desarmado, você pode causar 1d8 de dano Contundente em vez do dano normal. A partir do 11º nível, esse dano aumenta para 1d10.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/18/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"269dfb26-53d7-8bfe-a35d-cb907a6700fb","registro_id":"8723754f-2a34-86e9-a66f-61ff6f2ac182","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Regeneração Norlock","nome_original":"Regeneração Norlock","descricao_pt":"Seu organismo consegue reconstruir rapidamente tecidos danificados. Como uma Ação Bônus, você pode gastar um de seus Dados de Vida. Role o dado e recupere uma quantidade de Pontos de Vida igual ao resultado + seu modificador de Constituição. Você pode utilizar esta característica um número de vezes igual ao seu Bônus de Proficiência e recupera todos os usos após terminar um Descanso Longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/18/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"fcfb1787-1469-807e-acb7-95b0d4d86bb1","registro_id":"ec910ddc-e0da-83b6-a201-0e39b6b119ea","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Escalada Subterrânea","nome_original":"Escalada Subterrânea","descricao_pt":"Seus membros são adaptados para movimentação pelas cavernas e formações rochosas de seu mundo natal. Você possui Deslocamento de Escalada de 9 metros (30 pés). Além disso, pode escalar superfícies difíceis sem precisar realizar um teste de Força (Atletismo), desde que a superfície ofereça alguma forma de apoio ou aderência.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/18/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"57ae3520-39b7-8b07-ad61-986678432d4e","registro_id":"863f09c2-d2a6-8e7e-ad2c-1a85ca69d9a0","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Visão Subterrânea","nome_original":"Visão Subterrânea","descricao_pt":"Seus olhos são adaptados às regiões subterrâneas praticamente desprovidas de luz. Você possui Visão no Escuro com alcance de 120 pés (36 metros).","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/18/traits/4","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"46c88657-45d3-8630-a73d-b26315f0c0bb","registro_id":"b220bfde-53d7-8bf1-af1e-7506617a958a","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Forma Natural","nome_original":"Forma Natural","descricao_pt":"Enquanto estiver fora do Exotraje, você assume sua verdadeira forma gelatinosa. Nesta forma, você possui as seguintes características:\n\nSua CA é 10.\nSua vitalidade máxima é a metade do total conferido por sua classe (arredondado para cima).\nVocê pode se deformar para atravessar qualquer abertura com pelo menos 2,5 cm de largura, desde que não esteja carregando objetos grandes demais para atravessá-la.\nVocê pode entrar e permanecer dentro de recipientes ou espaços capazes de comportar sua massa.\nVocê não pode falar, realizar ataques, utilizar armas ou manusear ferramentas/objetos que exijam mãos ou estruturas semelhantes.\nVocê possui Resistência a dano Contundente, Cortante e Perfurante causado por armas não mágicas.\nVocê possui Deslocamento de Escalada de 20 pés.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/19/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"e1ceb89b-4510-8756-a70c-ee8ce5edaee7","registro_id":"e0a03546-0f5f-8d18-a873-08db1ddd6653","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Exotraje N0-V4","nome_original":"Exotraje N0-V4","descricao_pt":"Você possui um Exotraje desenvolvido especificamente para acomodar e interagir com seu corpo.\n\nSe estiver em sua Forma Natural, você pode vestir seu Exotraje usando uma ação, desde que ele esteja disponível em até 5 pés de você. Um Exotraje só pode ser usado pelo N0-V4 para o qual foi construído ou adaptado.\n\nEnquanto estiver dentro dele, você pode falar através do sistema de comunicação do traje, manipular objetos, utilizar armas, ferramentas e equipamentos normalmente, mas não pode vestir armaduras. Sua CA se torna 16, e você pode receber os benefícios de um escudo (interpretado como um escudo acoplado ao traje). Você recebe um total de Vida Falsa igual ao dobro dos seus pontos de vida totais, representando a durabilidade do Exotraje. Seu deslocamento base se torna 30 pés, e seu tamanho se torna Médio.\n\nPara efeitos que exijam um alvo Humanóide (como Imobilizar Pessoa), você conta como Construto enquanto está dentro do traje. Você não recebe imunidades de Construto. O Exotraje é uma máquina utilizada pelo N0-V4 e não faz parte de seu organismo.\n\nSe o traje for destruído, inutilizado ou precisar ser abandonado, o N0-V4 continua vivo em sua Forma Natural, mas perde todas as características fornecidas pelo Exotraje até conseguir repará-lo ou obter outro traje compatível. A Forma Natural do N0-V4 pode abandonar um Exotraje inutilizado normalmente.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/19/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"795e1917-988b-85c6-a120-021f81c092a3","registro_id":"93f0cc4d-1653-89bb-a59c-897535403514","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Sistema de Mobilidade","nome_original":"Sistema de Mobilidade","descricao_pt":"Escolha uma das seguintes opções ao criar seu personagem:\n\nTerrestre Aprimorado: Seu Deslocamento terrestre aumenta para 40 pés.\nEscalador: Você recebe Deslocamento de Escalada de 30 pés.\nAquático: Você recebe Deslocamento de Natação de 40 pés, e seu Exotraje pode funcionar normalmente enquanto estiver completamente submerso.\nPropulsor: Você recebe Deslocamento de Voo de 30 pés.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/19/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"de84a180-1931-8d59-aa7a-9c84ecd31d00","registro_id":"c5aebae3-103a-8a66-adde-b41e6c19b91d","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Módulo Especializado","nome_original":"Módulo Especializado","descricao_pt":"Escolha um dos seguintes módulos para o seu Exotraje:\n\nMódulo Defensivo: Sistemas adicionais de proteção reforçam seu Exotraje. Enquanto estiver utilizando o traje, você recebe +1 de bônus na CA.\nMódulo de Armamento: Uma arma de energia é integrada ao seu Exotraje (Arma marcial à distância, Dano: 1d8 Energia, Alcance: 12/36m, Munição ilimitada). Utiliza Destreza para jogadas de ataque e dano.\nMódulo Utilitário: Escolha uma ferramenta. Essa ferramenta é integrada ao seu Exotraje e pode ser estendida ou recolhida. Você ganha +1 em testes com essa ferramenta e proficiência nela enquanto usa o traje.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/19/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"f682c418-263b-8bcf-a650-cd644806b5d0","registro_id":"a3256193-bfd5-893a-a8b0-14a17184d44c","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Blindagem Adaptativa","nome_original":"Blindagem Adaptativa","descricao_pt":"Escolha um dos seguintes tipos de dano para receber Resistência enquanto estiver utilizando seu Exotraje:\n\nÁcido\nElétrico\nFogo\nFrio","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/19/traits/4","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"f7723a8c-ec33-8930-abb5-b1630311e6ea","registro_id":"ebeadc6a-fe4b-8d32-ab5e-d8724fada6ba","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Modo de Emergência","nome_original":"Modo de Emergência","descricao_pt":"Quando sua Vida Falsa é reduzida a 0, o Exotraje não desliga imediatamente. Ele entra em Modo de Emergência por 1 minuto, durante o qual:\n\nSua CA cai para 12.\nSeu Deslocamento cai para 20 pés.\nVocê não pode usar seu Módulo Especializado nem sua Blindagem Adaptativa.\nVocê ainda pode falar, mover-se e manipular objetos.\nVocê não pode recuperar Vida Falsa por nenhum meio durante o Modo de Emergência.\n\nAo final do Modo de Emergência, o Exotraje desliga completamente, e você é forçado a sair para sua Forma Natural. Se você sair voluntariamente antes disso, o Modo de Emergência termina imediatamente.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/19/traits/5","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"660b89aa-35d0-83e9-a657-028c150e3be8","registro_id":"63dfb363-1703-81ca-a5f0-8f67f4660bb9","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Auto-Reparo","nome_original":"Auto-Reparo","descricao_pt":"Quando o traje está danificado, você pode permanecer dentro dele para executar um auto-reparo durante seus descansos:\n\nDescanso Curto: O Exotraje recupera Vida Falsa igual ao seu nível de jogador × 5.\nDescanso Longo: O Exotraje recupera toda a Vida Falsa.\n\nQuando você é alvo de um efeito de magia curativa enquanto está vestindo o traje e possui menos que o máximo de Vida Falsa, a cura restaura Vida Falsa primeiro. Qualquer excedente cura seus PV reais.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/19/traits/6","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"b90f32eb-8150-8ff7-ad07-1894029001bf","registro_id":"200edb74-08bb-818e-ae01-3b141ac5f5d5","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Substituição do Exotraje","nome_original":"Substituição do Exotraje","descricao_pt":"Um Exotraje substituto pode ser encomendado a um artesão N0-V4 ou construído por alguém com proficiência em Ferramentas de Funileiro e acesso a materiais raros.\n\nTempo: 1d4 + 2 dias de trabalho.\nCusto: 200 PO em materiais.\nAdaptação: Um Exotraje construído para outro N0-V4 exige 1 dia de adaptação antes de poder ser usado.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/19/traits/7","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"a7fe099e-6cbd-8c9f-a848-58281feb1468","registro_id":"05724e04-4dcd-8c34-ab8e-1854a3ff163d","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Visão no Escuro","nome_original":"Visão no Escuro","descricao_pt":"Acostumado a longos períodos de escuridão, você possui Visão no Escuro com alcance de 60 pés.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/20/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"95b2f77d-b557-8638-a0a8-c3ff2abc9109","registro_id":"59819d1a-b43f-8b9c-af87-5eb590c55dd5","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Passo Veloz","nome_original":"Passo Veloz","descricao_pt":"Quando você não estiver usando armadura pesada, seu Deslocamento aumenta em 1,5 m. Além disso, quando realizar a ação Disparada, você pode ignorar terreno difícil até o final do turno.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/20/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"4e643391-f8f1-883b-a2a0-3fb6d3829566","registro_id":"c0adbc55-7be2-8d72-a92f-6ffcdce81b69","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Laços Espírituais","nome_original":"Laços Espírituais","descricao_pt":"Você possui proficiência em Religião e pode se comunicar telepaticamente com criaturas que estejam a até 30 pés de você, desde que compartilhem um idioma com você.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/20/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"56c8d767-b1ee-84dd-a48e-f318d2146254","registro_id":"ce925d2c-bdc7-88a7-a7b1-721177c2416f","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Desprendimento Espiritual","nome_original":"Desprendimento Espiritual","descricao_pt":"Você pode tentar se concentrar em uma criatura que possa ver em até 90 pés, acessando seus sentidos. Uma criatura não voluntária deverá realizar um teste de sabedoria, ou permitirá que você veja e sinta tudo o que ela sentir. A criatura saberá que seu corpo está sendo invadido. Você pode se locomover e agir normalmente enquanto nesse estado, que pode durar até 1 minuto ou até você encerrá-lo. No final do turno da criatura, enquanto você estiver invadindo seus sentidos, ela poderá realizar o teste novamente. Se passar, te expulsará do corpo. Você também é expulso caso perca a concentração. A partir do 11° nível, criaturas inimigas não perceberão sua presença em seus corpos. Você pode usar essa característica um número de vezes igual ao seu bônus de proficiência e recupera seus usos num Descanso Longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/20/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"f363630c-41b6-8ff9-a9bb-f13eb0055181","registro_id":"e2b36eb1-1a61-8976-adf2-62fe33ac1dd3","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Espiar Ego","nome_original":"Espiar Ego","descricao_pt":"Você pode energizar seus olhos para enxergar a silhueta do espírito de criaturas num raio de 30 pés. Você não pode enxergar através de barreiras mágicas ou paredes mais grossas que 30 cm. A duração do efeito é de 1 turno, e você pode usar essa característica duas vezes por Descanso Curto. No 11° Nível, a duração passa a ser 1 minuto.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/20/traits/4","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"6214e7cd-6349-8807-add9-bab56f144a34","registro_id":"e50c45b7-df8e-8276-af37-8b9923f4cde5","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Devorar Espírito","nome_original":"Devorar Espírito","descricao_pt":"Ao eliminar uma criatura, você pode usar sua reação para absorver parte da essência vital dela para potencializar técnicas específicas:\n\nAura Defensiva: Você protege o corpo usando a energia absorvida, dando Desvantagem no próximo Ataque realizado contra você.\nPropulsão Espiritual: Seu deslocamento aumenta em 15 pés até o final deste turno.\nCura Piedosa: Você converte a energia absorvida para curar seu corpo ou uma criatura aliada em até 30 pés numa quantidade igual ao seu bônus de proficiência.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/20/traits/5","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"ee3f591a-d4cc-8dad-a740-8c1468fa5955","registro_id":"3f31749a-078a-8ccf-a4c2-b6d5ff8bb7a2","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Visão no Escuro","nome_original":"Visão no Escuro","descricao_pt":"Você tem Visão no Escuro com um alcance de 18 metros (60ft).","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/21/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"b6b7f556-2071-8100-a64c-c85e07e1a996","registro_id":"44ca4430-db62-8802-a381-c15b8e8f45fc","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Aderência Zoldyana","nome_original":"Aderência Zoldyana","descricao_pt":"Suas mãos e pés possuem estruturas microscópicas que permitem aderir facilmente a superfícies. Você possui Deslocamento de Escalada igual ao seu Deslocamento normal e pode escalar superfícies difíceis, incluindo paredes, sem precisar realizar um teste de atributo, desde que possua mãos e pés disponíveis para se prender à superfície.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/21/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"f9ea23b2-632a-85c7-a6e5-ca554253ceed","registro_id":"6333479e-93f8-8aa1-a03e-337652b42820","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Cauda Poderosa","nome_original":"Cauda Poderosa","descricao_pt":"Sua longa cauda possui musculatura suficientemente desenvolvida para ser utilizada como arma. Quando realiza um Ataque Desarmado, você pode atacar utilizando sua cauda. Em um acerto, ela causa 1d6 + seu modificador de Força como dano Contundente em vez do dano normal do Ataque Desarmado.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/21/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"3d7c3694-9cec-89cb-a43c-09978b6c81f1","registro_id":"1d16329a-a45f-8e31-a456-4065c0b2b27f","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Regeneração Acelerada","nome_original":"Regeneração Acelerada","descricao_pt":"Seu organismo consegue reparar ferimentos em uma velocidade extraordinária. Como uma Ação Bônus, você pode gastar um de seus Dados de Vida, rolá-lo e recuperar uma quantidade de Pontos de Vida igual ao resultado da rolagem + seu modificador de Constituição. Você pode utilizar esta característica um número de vezes igual ao seu Bônus de Proficiência e recupera todos os usos após terminar um Descanso Longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/21/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"2ef4d68c-2953-8db8-aa88-0b2ad608d3d5","registro_id":"0d4864b2-1e82-8e8f-a756-f565b40f838a","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Regeneração de Membros","nome_original":"Regeneração de Membros","descricao_pt":"Seu corpo é capaz de reconstruir partes perdidas. Ao terminar um Descanso Longo, você pode regenerar completamente uma parte externa perdida ou severamente danificada do corpo, como um dedo, olho ou cauda. Membros maiores, como braços ou pernas, exigem 7 dias para serem completamente regenerados. Esse processo ocorre naturalmente enquanto você estiver vivo e possuir alimentação suficiente.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/21/traits/4","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"35abb478-f590-8549-a5f7-32999e9f7dc8","registro_id":"319fc5e9-b7c2-800e-a91e-ff8c96f94053","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Último Recurso","nome_original":"Último Recurso","descricao_pt":"Como uma reação, ao ser atacado, você pode sacrificar sua cauda para distrair criaturas inimigas ou para se tornar mais leve, adicionando +5 de CA até o final desse turno. Você perde o uso dessa característica e da característica \"Cauda Poderosa\" até que esse membro se regenere.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/21/traits/5","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"8aaeb97b-433b-8aa7-ad9c-1b21d57bd08f","registro_id":"74540ccf-3a56-8d04-ab73-84eee822cdd1","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Força Zorak","nome_original":"Força Zorak","descricao_pt":"O valor máximo do seu atributo de Força é 23, em vez de 20. Além disso, você possui Vantagem em testes de Força (Atletismo).","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/22/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"cec2dcf0-bf3a-85a3-a962-c3d2066da6d1","registro_id":"776337d3-c15f-8454-a92b-d8e247a60059","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Corpo Super-Resistente","nome_original":"Corpo Super-Resistente","descricao_pt":"Seu corpo possui resistência extraordinária contra impactos e ferimentos. Enquanto não estiver utilizando armadura, sua Classe de Armadura é 16. A partir do 11º nível, sua Classe de Armadura Natural aumenta para 18. Você ainda pode utilizar um escudo e receber normalmente o bônus de CA fornecido por ele.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/22/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"96e36b5b-40a0-87a0-a0cc-5d4797992352","registro_id":"1f923059-6141-87e8-a390-0da572a9b820","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Golpes Poderosos","nome_original":"Golpes Poderosos","descricao_pt":"Seus golpes são capazes de causar danos muito superiores aos de um humanoide comum. Quando realiza um Ataque Desarmado, você pode causar 1d8 de dano Contundente em vez do dano normal. Você usa seu modificador de Força no acerto e dano, e é proficiente. A partir do 11º nível, esse dano aumenta para 1d10.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/22/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"aae2d4ae-95f5-8625-a883-770ccb140f0d","registro_id":"1679f18a-51a5-87ce-a7b3-c370e23422b9","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Impulso Zorak","nome_original":"Impulso Zorak","descricao_pt":"Seu corpo é capaz de produzir explosões repentinas de velocidade e força. Você pode realizar a ação Disparada (Dash) como uma Ação Bônus. Além disso, as distâncias dos seus Saltos em Distância e Saltos em Altura são duplicadas, e você não precisa realizar uma corrida de 3 metros antes do salto para alcançar a distância máxima. Seus saltos continuam limitados pelo Deslocamento disponível durante o turno.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/22/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"9ca3403d-f2df-8cc2-a272-deb293971631","registro_id":"ef8d590d-25a1-8ccc-a765-76c05eba8ac9","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Investida","nome_original":"Investida","descricao_pt":"Você recebe o talento Investida (Charger). Você recebe todos os benefícios desse talento e deve cumprir normalmente seus requisitos e condições para utilizá-lo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/22/traits/4","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"38fcb75b-a41f-8d3b-a0a6-9fa56f366b13","registro_id":"b0c9a25e-b5f7-8212-a8ec-8da47aac5e6b","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Transe No Xeol","nome_original":"Transe No Xeol","descricao_pt":"Você não precisa dormir. Em vez disso, entra em um estado de meditação profunda para se conectar à fonte de Aether que flui por toda a vida. Você permanece consciente do ambiente durante o transe. Na conclusão de um Descanso Longo, você recebe os benefícios normais e Pontos de Vida temporários iguais ao seu Nível + modificador de Constituição. Esses PV temporários duram até serem perdidos ou até o fim do seu próximo Descanso Longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/23/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"a9e4acf9-f422-86c9-a955-b32c3307f0db","registro_id":"6d9bcf83-654b-8bc3-a54b-5cbc098800db","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Conhecimento Nomádico","nome_original":"Conhecimento Nomádico","descricao_pt":"Escolha uma das seguintes perícias para se tornar proficiente. Ao atingir o 5º nível, você adiciona o dobro do seu bônus de proficiência em testes para a perícia escolhida:\n\nAcrobacia\nAtletismo\nNatureza\nSobrevivência","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/23/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"f50fc721-009f-8ac8-abd2-ab09a34acd28","registro_id":"dea92b6b-cf0b-87a5-a6d4-db40ccdf42e8","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Infusão Espiritual","nome_original":"Infusão Espiritual","descricao_pt":"Escolha uma arma com a qual você seja proficiente. Você pode infundir sua energia etérea por 1 minuto na arma como uma Ação Bônus, ganhando o seguinte benefício:\n\nEnquanto infundida, ela causa +1d4 de dano do tipo Radiante ou Necrótico (à sua escolha).\n\nCaso a arma esteja conectada a um Cristal de Aether, você também soma seu modificador de Constituição ao dano.\n\nVocê pode usar essa característica um número de vezes igual ao seu bônus de proficiência por Descanso Longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/23/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"24b163e0-b65b-8b86-ad16-158e6a3af7c1","registro_id":"9739637a-c996-854f-ae09-b99488d5d3cd","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Leitura Vital","nome_original":"Leitura Vital","descricao_pt":"Como uma Ação, você toca uma criatura viva e descobre uma informação sobre ela: se está envenenada, doente, amaldiçoada, enfeitiçada, com PV atuais abaixo do máximo, ou se é um morto-vivo. Você pode usar essa característica uma vez a cada Descanso Curto ou Longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/23/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"99db1a9f-c2ba-82d9-ad8d-c2925fdd21b7","registro_id":"79728674-605a-89a7-aed8-8fdb87a69b92","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Sintonia Aetheria","nome_original":"Sintonia Aetheria","descricao_pt":"Você pode gastar 1 minuto meditando para sentir a presença de criaturas vivas (ou de Aether concentrado) em um raio de 30 pés (9 metros). Você consegue identificar a direção da presença, mas não a localização exata. Você pode usar essa característica um número de vezes igual ao seu bônus de proficiência por Descanso Longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/23/traits/4","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"1bbd1d41-eca9-8f9f-af83-ace91b7e923b","registro_id":"3836d043-be1b-8e05-aff0-d9021a5815e9","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Resistência Mortal","nome_original":"Resistência Mortal","descricao_pt":"Você tem resistência à dano Necrótico.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/24/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"86ff9bf4-8842-864b-a6c5-8b25888e3c43","registro_id":"a5edc82d-a732-896f-a065-8ce5f398d9d0","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Visão no Escuro","nome_original":"Visão no Escuro","descricao_pt":"Você tem visão no escuro 60 pés.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/24/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"4f17ad06-7946-80c4-a698-681ffb6c4d84","registro_id":"a489c2a2-1fa5-8a52-a0c7-ec901d678bdd","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Herança de Asmodeus","nome_original":"Herança de Asmodeus","descricao_pt":"A essência de Asmodeus corre em seu sangue. Você possui vantagem em Testes de Resistência contra a condição Amedrontado. Além disso, você não pode ser magicamente colocado para dormir.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/24/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"f0cf028b-398d-85df-a42a-b42cc6229fe2","registro_id":"b4d0628b-aed8-8588-a059-b73e3d30265e","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Aparência Sobrenatural","nome_original":"Aparência Sobrenatural","descricao_pt":"Você possui proficiência em Intimidação ou Persuasão, à sua escolha.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/24/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"6389402a-fff2-80b1-ab6c-cc59e7cc2b5d","registro_id":"181260ea-602c-836d-abbb-cbc10749b66d","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Toque da Morte","nome_original":"Toque da Morte","descricao_pt":"Uma vez por turno, quando você acerta uma criatura com um ataque corpo a corpo, pode fazer com que o ataque cause dano necrótico adicional igual ao seu Bônus de Proficiência. Você pode usar essa característica um número de vezes igual ao seu bônus de proficiência e recupera seus usos com um descanso longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/24/traits/4","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"e904c590-6ad5-86d3-a78b-d1ef1726b52f","registro_id":"022b8b05-0a4b-8174-a6be-53ff2d137d7a","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Herdeiro do Submundo","nome_original":"Herdeiro do Submundo","descricao_pt":"Você conhece o truque Toque Arrepiante (Chill Touch). A partir do 3º nível, você pode conjurar Infligir Ferimentos (Inflict Wounds) uma vez sem gastar espaço de magia. Você recupera a capacidade de conjurar essa magia ao terminar um Descanso Longo. Atributo de Conjuração: escolha Inteligência, Sabedoria ou Carisma ao selecionar esta espécie.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/24/traits/5","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"210ae509-e5a5-8a08-a381-5c77b3a3ad24","registro_id":"ba44167b-f308-8508-a92d-7454259454ea","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Chifres","nome_original":"Chifres","descricao_pt":"Seus chifres podem ser usados em um ataque desarmado. Força é seu atributo de acerto e você causa 1d6 + seu modificador de Força como dano contundente.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/25/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"ace41cc1-ff64-838a-a7da-1b592e1885cc","registro_id":"a601c351-557c-8928-a1b7-eb475fa2ee46","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Investida Bestial","nome_original":"Investida Bestial","descricao_pt":"Ao se mover pelo menos 20 pés em linha reta e acertar um ataque de Chifres, o dano aumenta em 1d6. O alvo deve passar num Teste de Resistência de Força (CD = 8 + Bônus Proficiência + mod. Força) ou é empurrado 10 pés (isso não causa ataques de oportunidade).","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/25/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"6a0074fa-c719-81fc-ad17-7743b7b34260","registro_id":"a7be6ab3-9e47-8000-ac56-2a84f59721d7","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Salto Bestial","nome_original":"Salto Bestial","descricao_pt":"Você adiciona 1d8 pés à distância do seu salto.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/25/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"cf518793-6204-8cf5-ae92-61f628077082","registro_id":"7717e141-3db7-82de-ab56-cf126c3e8002","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Resistência Demoníaca","nome_original":"Resistência Demoníaca","descricao_pt":"Você tem resistência à dano Psíquico.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/25/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"852d5184-1e05-888c-a4e5-1682f959e2d6","registro_id":"a1b66175-134c-8d47-a793-7623e0649d33","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Fúria de Baphomet","nome_original":"Fúria de Baphomet","descricao_pt":"Você tem vantagem em Testes de Resistência para evitar ou encerrar os efeitos Amedrontado ou Enfeitiçado.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/25/traits/4","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"6c4874f5-68be-8329-a15b-f50cf7d991ef","registro_id":"25ce2c4f-56cb-89d3-a39b-0040194fd2a3","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Taumaturgia","nome_original":"Taumaturgia","descricao_pt":"Você conhece o truque Taumaturgia. Carisma é seu atributo de conjuração.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/25/traits/5","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"4b96c79a-ab24-8f9e-ab71-57581c499325","registro_id":"e5217f9f-ccb8-8586-aa78-5b247b2227b3","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Resistência Infernal","nome_original":"Resistência Infernal","descricao_pt":"Você tem resistência à dano de Fogo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/26/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"c349d98a-7fbf-80f8-a5cf-b82f6a3de2b6","registro_id":"0e2acfff-a96c-89fb-a4b7-87009d939d78","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Visão no Escuro","nome_original":"Visão no Escuro","descricao_pt":"Você tem visão no escuro 60 pés.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/26/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"ea2d04e9-7871-8706-ae45-f6e968ed7dea","registro_id":"e5059de1-758e-8852-ad59-8cd9cf539a9e","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Herança de Belial","nome_original":"Herança de Belial","descricao_pt":"A essência de Belial, Primordial da Guerra, corre em seu sangue. Quando você realiza um ataque e erra, pode usar sua Reação para rolar novamente o ataque. Você pode usar esta característica uma vez por Descanso Longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/26/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"74c40322-53b5-8f8e-abab-83426fc5bdca","registro_id":"c23b56e3-3a01-8e26-a3e8-a8fb1cfe3ab2","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Espírito de Guerra","nome_original":"Espírito de Guerra","descricao_pt":"Você possui vantagem em Testes de Resistência para evitar ou encerrar a condição Amedrontado.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/26/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"36e1a624-4eb7-8290-a72b-be7e12251d35","registro_id":"2bf3f16a-f7d6-8c62-ad0e-d8d3f80a017d","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Cauda Demoníaca","nome_original":"Cauda Demoníaca","descricao_pt":"Sua cauda pode manipular objetos leves. Você pode usá-la para abrir portas destrancadas, puxar ou empurrar objetos, apanhar objetos soltos ou realizar tarefas semelhantes. A cauda não pode realizar ataques nem executar tarefas que exijam a precisão de uma mão.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/26/traits/4","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"21a754ce-5890-819f-ae31-781ec19c6393","registro_id":"e203b881-f9bb-8555-a5c0-85781b708ca0","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Herdeiro do Submundo","nome_original":"Herdeiro do Submundo","descricao_pt":"Você conhece o truque Toque Arrepiante (Chill Touch). A partir do 3º nível, você pode conjurar Infligir Ferimentos (Inflict Wounds) uma vez sem gastar espaço de magia. Você recupera a capacidade de conjurar essa magia ao terminar um Descanso Longo. Atributo de Conjuração: escolha Inteligência, Sabedoria ou Carisma ao selecionar esta espécie.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/26/traits/5","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"eb6072dc-939d-826c-a1ea-d118980ca823","registro_id":"63b97565-091b-89bb-a7fe-eb3f5128cbfd","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Visão no Escuro","nome_original":"Visão no Escuro","descricao_pt":"Adaptados às profundezas de Tenebris, você possui Visão no Escuro com alcance de 60 pés.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/27/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"a118e5e6-5d36-8cd3-ade3-42c56a50d81f","registro_id":"e9bc7987-6329-8865-a31e-61c534edd491","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Disfarce Abissal","nome_original":"Disfarce Abissal","descricao_pt":"Sua carapaça e estrutura corporal podem se reorganizar para reproduzir a aparência de outras espécies de Tenebris. Você pode usar os efeitos da magia Disfarçar-se (Disguise Self) para assumir a aparência de outra raça nativa de Tenebris que conheça, alterando características como rosto, pele, carapaça, membros, olhos e demais traços físicos.\n\nVocê pode usar essa característica um número de vezes igual ao seu bônus de proficiência e recupera seus usos com um Descanso Curto.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/27/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"3ebdd689-2411-8002-a740-4f910d8be519","registro_id":"7ff9429e-d3f6-8f23-ace5-b2fc3e3f7aab","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Arma Natural Integrada","nome_original":"Arma Natural Integrada","descricao_pt":"Todos os Inamons possuem uma arma natural incorporada ao próprio corpo, desenvolvida a partir de suas estruturas orgânicas e mecânicas. Durante a criação do personagem, escolha uma arma com a qual seja proficiente. Essa arma passa a fazer parte do seu corpo e pode assumir diferentes formas, como:\n\nBraço de Lâmina: uma espada integrada ao antebraço.\nLançador de Espinhos: uma estrutura que dispara projéteis semelhantes a uma besta.\nGarras Retráteis: lâminas quitinosas que emergem dos dedos.\nCanhão Orgânico: uma arma de disparo integrada ao braço.\nArmas de Impacto: membros reforçados para golpes contundentes.\n\nA arma escolhida utiliza as estatísticas de uma arma oficial de D&D compatível com sua forma, incluindo dano, propriedades, alcance e tipo de dano. Ela é considerada uma arma natural e não pode ser desarmada. Você pode manifestar ou recolher sua arma integrada como uma Ação Bônus. Ela não pode ser substituída por outra arma durante um combate.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/27/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"b7f4210c-6e1b-8a63-a432-ece904b181ea","registro_id":"0241cfbc-69fd-83f8-a90e-2eee5d100d18","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Sobrecarga da Essência","nome_original":"Sobrecarga da Essência","descricao_pt":"Todo Inamon possui um núcleo que armazena energia da Essência, permitindo realizar um ataque devastador em situações extremas.\n\nComo uma Ação, você pode liberar essa energia em um disparo concentrado, formando um poderoso canhão de energia caótica.\n\nEscolha um ponto que possa ver a até 18 metros. Uma explosão ocorre em um raio de 3 metros ao redor desse ponto. Todas as criaturas na área devem realizar uma Salvaguarda de Destreza, com CD igual a 8 + seu Bônus de Proficiência + seu modificador de Constituição.\n\nEm uma falha, a criatura sofre 2d10 de dano de Energia. Em um sucesso, sofre metade do dano.\n\nIndependentemente do resultado, após utilizar a Sobrecarga da Essência, você não poderá utilizá-la novamente até terminar um Descanso Longo.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/27/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"9944b0a3-2eda-8478-a9d4-42ab1acfd381","registro_id":"f0a38af2-3e28-8bcf-a1b2-886f39afc90f","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Aprimoramentos Inamônicos","nome_original":"Aprimoramentos Inamônicos","descricao_pt":"Os Inamons podem modificar sua estrutura corporal para adquirir diferentes capacidades. No 1º nível, escolha um dos aprimoramentos abaixo. Ao atingir o 7º nível, você pode escolher um segundo aprimoramento.\n\nCada aprimoramento pode ser substituído por outro ao terminar um Descanso Longo. Você pode reorganizar seus aprimoramentos durante esse descanso, respeitando o número de aprimoramentos disponíveis pelo seu nível.\n\nAsas Abissais: Você desenvolve asas quitinosas ou membranosas, capazes de sustentar seu corpo durante o voo. Você recebe Deslocamento de Voo de 9 metros.\n\nPernas Aprimoradas: Suas pernas são reforçadas com estruturas musculares e mecânicas, permitindo deslocamentos rápidos e explosivos. Seu Deslocamento terrestre aumenta em 3 metros, passando a ser de 12 metros.\n\nCarapaça Reforçada: Sua carapaça recebe placas adicionais de quitina, reforçadas por componentes arcanos e estruturas resistentes. Enquanto não estiver utilizando armadura, sua Classe de Armadura é 16. A partir do 11º nível, sua Classe de Armadura aumenta para 18. Você pode utilizar escudos normalmente, recebendo seus benefícios, desde que tenha um membro livre e compatível para empunhá-los.\n\nQuatro Braços: Seu corpo desenvolve um segundo par de braços, permitindo manipular objetos e equipamentos simultaneamente. Você pode utilizar seus braços adicionais para manipular objetos, interagir com o ambiente, abrir portas, carregar itens e realizar outras tarefas que normalmente exigiriam uma mão livre. Esses braços não concedem ataques adicionais, não permitem realizar mais ações ou Ataques de Oportunidade e não possibilitam empunhar armas ou escudos extras para obter benefícios adicionais. Além disso, você recebe Deslocamento de Escalada de 9 metros e pode escalar superfícies difíceis sem precisar realizar testes de atributo, desde que tenha os membros disponíveis para se apoiar.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/27/traits/4","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"664b6298-68cd-86c8-ac63-ac128ee81b0d","registro_id":"75f3bd79-ce06-8932-a17e-1c7cbc47eae7","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Visão no Escuro","nome_original":"Visão no Escuro","descricao_pt":"Você tem visão no escuro 60 pés.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/28/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"43d4b3bb-f456-88cc-a497-14c6dfc8fab2","registro_id":"373dd14c-c5c7-85a1-a562-69a03c54ee07","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Resistência à Magia","nome_original":"Resistência à Magia","descricao_pt":"Você tem vantagem em testes de resistência contra os efeitos que lhe causem encantamento, surdez ou cegueira, e tem vantagem em testes para decifrar ilusões.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/28/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"7f202af2-7189-8118-aeae-bff61d1d86c5","registro_id":"471d9da5-3f97-86c4-a8d8-4c55d8d34c93","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Imunidade à Veneno","nome_original":"Imunidade à Veneno","descricao_pt":"Você é imune a dano de veneno e à condição envenenado.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/28/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"418cfc2a-2241-8da3-a448-f185b1533bf9","registro_id":"d37dd603-82b4-8850-a840-52ec7e59889b","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Conjuração Inata","nome_original":"Conjuração Inata","descricao_pt":"Conhece o truque Rajada de Veneno. Pode conjurar Amizade Animal ilimitadamente (apenas em serpentes).\n\nA partir do 3º nível, pode conjurar Sugestão uma vez a cada descanso. O atributo de conjuração é Carisma.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/28/traits/3","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"cf997379-def2-8da2-a998-8803117494e6","registro_id":"fea902ef-43dd-835b-a45f-91196f9c2291","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Resistência Pútrida","nome_original":"Resistência Pútrida","descricao_pt":"Você tem resistência à dano Ácido.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/29/traits/0","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"2ab0e21d-f781-8139-a3c6-37559cd9bc15","registro_id":"8b3a9fab-e7ce-8b5a-a17e-fb2ceac1fd26","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Olhos Compostos","nome_original":"Olhos Compostos","descricao_pt":"Você tem proficiência em Percepção. Além disso, você não sofre desvantagem em testes de Sabedoria (Percepção) feitos para enxergar criaturas ou objetos que estejam a até 30 pés de você.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/29/traits/1","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"0cb2e82b-e2a0-853e-aff0-c5f379a3d5a5","registro_id":"4ff3f03e-d42a-89c7-ae9d-0bb402b1778c","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_pt":"Reflexos de Mosca","nome_original":"Reflexos de Mosca","descricao_pt":"Uma vez por descanso longo, se uma criatura que você possa ver realizar um ataque contra você, você pode usar sua Reação para impor desvantagem nesse ataque.","descricao_html":"","revisado_2024":false,"automacao":"manual","caminho_fonte":"data/races.json","ancora_fonte":"/29/traits/2","hash_fonte":"6b83f626fe5b7e913d869bf0e611445ec57f2bf70ffb07cd2fb2bc998b545f40"},{"id":"cfe2bc0f-3915-8766-ac55-fa90e0c65da8","registro_id":"b0e7bcde-fe68-8517-abcf-dccc5c670a1f","conjunto_regras_codigo":"dnd-5e-2024","fonte_id":"7b61f355-967a-8e76-adc4-76df2afc71f1","nome_p