INSERT INTO public.compendio_ferramentas(revisao_id,atributo_codigo,utilizacao_pt) SELECT e.revisao_id,e.atributo_codigo,e.utilizacao_pt FROM jsonb_populate_recordset(NULL::public.compendio_ferramentas,'[{"revisao_id":"a2a04150-4f2c-8a90-a1c7-8ee3a0baf78c","atributo_codigo":"for","utilizacao_pt":"Selar ou abrir uma porta ou recipiente (CD 20)\nAríete Portátil, Baliza, Barril, Baú, Cajado, Clava, Clava Grande, Escada, Tocha"},{"revisao_id":"94cf5a41-cfa1-8f17-a168-b9e402c216d5","atributo_codigo":"sab","utilizacao_pt":"Elaborar o mapa de uma pequena área (CD 15)\nMapa"},{"revisao_id":"d76de6db-cf2f-8e24-ad61-d5f8c7a9cd8c","atributo_codigo":"des","utilizacao_pt":"Moldar a estética de um item de couro (CD 10)\nAlgibeira, Aljava, Armadura de Couro, Armadura de Couro Batido, Cantil, Chicote, Estojo de Mapa ou Pergaminho, Estojo de Virotes de Besta, Funda, Gibão de Peles, Mochila, Pergaminho"},{"revisao_id":"a60dece1-25d2-836c-aa2d-e16426bde162","atributo_codigo":"des","utilizacao_pt":"Entalhar um padrão em madeira (CD 10)\nArmas à Distância (exceto Funda, Mosquete e Pistola), Cajado, Caneta Tinteiro, Clava, Clava Grande, Dardos, Flechas, Foco Arcano, Foco Druídico, Virotes"},{"revisao_id":"8dc8c81a-ecdc-823c-a0e2-ef991d4ab996","atributo_codigo":"for","utilizacao_pt":"Forçar a abertura de uma porta ou recipiente (CD 20)\nQualquer arma Corpo a Corpo (exceto Cajado, Chicote, Clava, Clava Grande), armadura Média (exceto Gibão de Peles), armadura Pesada, Arpéu e Gancho, Balas de Arma de Fogo, Balas de Funda, Balde, Corrente, Esferas de Metal, Estacas de Ferro, Estrepes, Panela de Ferro, Pé de Cabra"},{"revisao_id":"94c5edcb-7b10-840b-a8fd-92e569528d0f","atributo_codigo":"des","utilizacao_pt":"Monte um item Minúsculo composto de sucata, que se desfaz em 1 minuto (CD 20)\nApito Sinalizador, Armadilha de Caça, Cadeado ou Fechadura, Caixa para Fogo, Espelho, Grilhões, Lanterna Coberta, Lanterna Foca-Facho, Mosquete, Pá, Pistola, Pote, Sino"},{"revisao_id":"4f2c2156-ada4-8bb0-a3db-