INSERT INTO public.compendio_criatura_acoes(id,revisao_id,nome_pt,tipo,descricao_pt,bonus_ataque,cd) SELECT e.id,e.revisao_id,e.nome_pt,e.tipo,e.descricao_pt,e.bonus_ataque,e.cd FROM jsonb_populate_recordset(NULL::public.compendio_criatura_acoes,'[{"id":"4a76c974-3cb8-8cfb-aabb-fa72abfc31d2","revisao_id":"4b52366b-40b2-89a0-a345-04eb3f196626","nome_pt":"Liga de Aço","tipo":"acao","descricao_pt":"Liga de Aço. Adicione seu Bônus de Proficiência a qualquer teste de atributo ou salvaguarda que o Defensor de Aço fizer.","bonus_ataque":null,"cd":null},{"id":"7f6f7adc-9e56-8f19-a1ee-460cb1994d66","revisao_id":"4b52366b-40b2-89a0-a345-04eb3f196626","nome_pt":"Garra Energizada","tipo":"acao","descricao_pt":"Garra Energizada. Rolagem de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque de magia, alcance 1,5 m. Acerto: 1d8 + 2 + seu modificador de Inteligência de dano de Força.","bonus_ataque":null,"cd":null},{"id":"75279964-389f-8d34-a9c5-d8d3cb7a9e36","revisao_id":"4b52366b-40b2-89a0-a345-04eb3f196626","nome_pt":"Reparo (3/Dia)","tipo":"acao","descricao_pt":"Reparo (3/Dia). O defensor, ou um Construto ou objeto que ele possa ver a até 1,5 metro dele, recupera um número de Pontos de Vida igual a 2d8 + seu modificador de Inteligência.","bonus_ataque":null,"cd":null},{"id":"be32c3b3-c67c-8e0f-a12d-931bbff98a95","revisao_id":"4b52366b-40b2-89a0-a345-04eb3f196626","nome_pt":"Desviar Ataque","tipo":"reacao","descricao_pt":"Desviar Ataque. Gatilho: Uma criatura que o defensor pode ver a até 1,5 metro dele faz uma rolagem de ataque mirando em uma criatura diferente. Resposta: A criatura gatilho faz a rolagem de ataque com Desvantagem.","bonus_ataque":null,"cd":null},{"id":"ab0cf6b9-d360-868f-a0a1-bd48c39cd97f","revisao_id":"01125e3c-223e-8742-a18d-9fdc5319d121","nome_pt":"Traços","tipo":"traco","descricao_pt":"Traços","bonus_ataque":null,"cd":null},{"id":"2b776ab0-5679-80ba-a343-7e0142f2615f","revisao_id":"01125e3c-223e-8742-a18d-9fdc5319d121","nome_pt":"Devastador (requer Nível de Druida 10+)","tipo":"traco","descricao_pt":"Devastador (requer Nível de Druida 10+). Quando você entra no espaço de um inimigo que é pelo menos um tamanho menor que você pela primeira vez em um turno, aquela criatura está sujeita ao seguinte efeito. Teste de Resistência de Força: CD igual à sua CD de resistência de magia. Falha: O alvo fica com a condição Deitado. Se o alvo já estiver com a condição Deitado, ele sofre 2d6 de dano de Impacto.","bonus_ataque":null,"cd":null},{"id":"9e612ddb-6ec4-8b8c-a936-eb56e259366f","revisao_id":"01125e3c-223e-8742-a18d-9fdc5319d121","nome_pt":"Monstro de Cerco","tipo":"traco","descricao_pt":"Monstro de Cerco. Você causa dano dobrado a objetos e estruturas.","bonus_ataque":null,"cd":null},{"id":"5312dc58-cc60-86af-a81e-68bac83c1687","revisao_id":"01125e3c-223e-8742-a18d-9fdc5319d121","nome_pt":"Ações","tipo":"traco","descricao_pt":"Ações","bonus_ataque":null,"cd":null},{"id":"ac592070-705f-8c8a-a1dd-bb08889bfc85","revisao_id":"01125e3c-223e-8742-a18d-9fdc5319d121","nome_pt":"Multiataque (requer Nível de Druida 5+)","tipo":"traco","descricao_pt":"Multiataque (requer Nível de Druida 5+). Você faz dois ataques de Despedaçar.","bonus_ataque":null,"cd":null},{"id":"0ec70a26-9850-81c5-a6be-ee5f0fe9b579","revisao_id":"01125e3c-223e-8742-a18d-9fdc5319d121","nome_pt":"Despedaçar","tipo":"traco","descricao_pt":"Despedaçar. Rolagem de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque de magia, alcance 3 m. Acerto: 1d8 + seu modificador de Sabedoria de dano de Corte.","bonus_ataque":null,"cd":null},{"id":"f8a4de64-96ea-8f19-a0d1-f317c8f03075","revisao_id":"01125e3c-223e-8742-a18d-9fdc5319d121","nome_pt":"Sopro Incandescente","tipo":"traco","descricao_pt":"Sopro Incandescente. Você gasta um espaço de magia de nível 1+. Teste de Resistência de Destreza: CD igual à sua CD de resistência de magia, cada criatura em uma Linha de 1,5 m de largura e 18 m de comprimento. Falha: 2d8 de dano Radiante por nível do espaço de magia gasto + seu modificador de Sabedoria. Sucesso: Metade do dano.","bonus_ataque":null,"cd":null},{"id":"8b6fa4e3-8ec5-800a-a992-2cd9cd1ff74e","revisao_id":"2574adc3-1a13-8888-a1b5-54698fd10cc4","nome_pt":"Traços","tipo":"traco","descricao_pt":"Traços","bonus_ataque":null,"cd":null},{"id":"cd881f1c-467b-8bf2-ad24-8c8846567624","revisao_id":"2574adc3-1a13-8888-a1b5-54698fd10cc4","nome_pt":"Anfíbio","tipo":"traco","descricao_pt":"Anfíbio. Você pode respirar ar e água.","bonus_ataque":null,"cd":null},{"id":"0a84514b-f9a3-8fb2-a43b-e132708f2084","revisao_id":"2574adc3-1a13-8888-a1b5-54698fd10cc4","nome_pt":"Fedorento Tóxico (requer Nível de Druida 10+)","tipo":"traco","descricao_pt":"Fedorento Tóxico (requer Nível de Druida 10+). Teste de Resistência de Constituição: CD igual à sua CD de resistência de magia, cada criatura de sua escolha que começa seu turno em uma Emanação de 3 metros originada de você. Falha: 2d4 de dano de Veneno, e o alvo fica com a condição Envenenado até o início de seu próximo turno.","bonus_ataque":null,"cd":null},{"id":"eb4cf5fa-75fa-84af-a469-541d692ddeba","revisao_id":"2574adc3-1a13-8888-a1b5-54698fd10cc4","nome_pt":"Ações","tipo":"traco","descricao_pt":"Ações","bonus_ataque":null,"cd":null},{"id":"bd774a2e-1524-8d39-af3c-c014bf4df034","revisao_id":"2574adc3-1a13-8888-a1b5-54698fd10cc4","nome_pt":"Multiataque (requer Nível de Druida 5+)","tipo":"traco","descricao_pt":"Multiataque (requer Nível de Druida 5+). Você faz dois ataques de Despedaçar.","bonus_ataque":null,"cd":null},{"id":"17b1b3bd-fdb5-8ddc-abd3-4907ffcdb55b","revisao_id":"2574adc3-1a13-8888-a1b5-54698fd10cc4","nome_pt":"Despedaçar","tipo":"traco","descricao_pt":"Despedaçar. Rolagem de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque de magia, alcance 3 m. Acerto: 1d8 + seu modificador de Sabedoria de dano de Impacto.","bonus_ataque":null,"cd":null},{"id":"c4c5501d-75bc-81b2-a74a-9b6da341b7c5","revisao_id":"2574adc3-1a13-8888-a1b5-54698fd10cc4","nome_pt":"Reações","tipo":"traco","descricao_pt":"Reações","bonus_ataque":null,"cd":null},{"id":"103584da-819a-8bbd-aba0-eadb0b001779","revisao_id":"2574adc3-1a13-8888-a1b5-54698fd10cc4","nome_pt":"Nuvem de Tinta","tipo":"traco","descricao_pt":"Nuvem de Tinta. Gatilho: Você sofre dano. Resposta: Você gasta um espaço de magia de nível 1+ e libera uma nuvem de tinta que preenche um Cubo de 4,5 metros de raio centrado em você, e se move até seu Deslocamento. O Cubo está Altamente Obscurecido. Ele dura 1 minuto ou até que uma corrente forte ou vento (como o criado por Lufada de Vento) o disperse.","bonus_ataque":null,"cd":null},{"id":"66ed150f-8ca5-829b-a474-37d73910dece","revisao_id":"57bb6339-3f9a-8057-ac2a-006e628715c7","nome_pt":"Traços","tipo":"traco","descricao_pt":"Traços","bonus_ataque":null,"cd":null},{"id":"2e159bf3-6c15-8bde-a7e2-3cf8b74270a2","revisao_id":"57bb6339-3f9a-8057-ac2a-006e628715c7","nome_pt":"Voo Rápido","tipo":"traco","descricao_pt":"Voo Rápido. Você não provoca Ataques de Oportunidade quando voa para fora do alcance de um inimigo.","bonus_ataque":null,"cd":null},{"id":"4c07c7bc-0157-8489-a9a3-8bcd908a0b20","revisao_id":"57bb6339-3f9a-8057-ac2a-006e628715c7","nome_pt":"Mente Colmeia (requer Nível de Druida 10+)","tipo":"traco","descricao_pt":"Mente Colmeia (requer Nível de Druida 10+). Quando você assume esta forma, forja um vínculo telepático com um número de criaturas de sua escolha que você pode ver e que podem se comunicar em pelo menos um idioma; o número máximo de criaturas é igual ao seu nível de Druida. Você e as criaturas escolhidas podem se comunicar telepaticamente entre si, independentemente de compartilharem um idioma, enquanto estiverem no mesmo plano.","bonus_ataque":null,"cd":null},{"id":"f57068ca-1d99-8c13-a39f-32a15571fe3a","revisao_id":"57bb6339-3f9a-8057-ac2a-006e628715c7","nome_pt":"Ações","tipo":"traco","descricao_pt":"Ações","bonus_ataque":null,"cd":null},{"id":"0d55cd1d-ed01-841c-a0ff-3a710e3a2a7b","revisao_id":"57bb6339-3f9a-8057-ac2a-006e628715c7","nome_pt":"Multiataque (requer Nível de Druida 5+)","tipo":"traco","descricao_pt":"Multiataque (requer Nível de Druida 5+). Você faz dois ataques de Despedaçar.","bonus_ataque":null,"cd":null},{"id":"0f0f48df-9e46-87af-a698-a6439fc27027","revisao_id":"57bb6339-3f9a-8057-ac2a-006e628715c7","nome_pt":"Despedaçar","tipo":"traco","descricao_pt":"Despedaçar. Rolagem de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque de magia, alcance 3 m. Acerto: 1d8 + seu modificador de Sabedoria de dano de Perfuração.","bonus_ataque":null,"cd":null},{"id":"5c41cb6b-9acd-80d8-a8bd-15b52039491c","revisao_id":"57bb6339-3f9a-8057-ac2a-006e628715c7","nome_pt":"Pólen Energizante","tipo":"traco","descricao_pt":"Pólen Energizante. Você gasta um espaço de magia de nível 1+ e emite uma nuvem de pólen curativo que pode restaurar um número de Pontos de Vida igual a 2d8 + cinco vezes o nível do espaço de magia gasto. Escolha qualquer número de criaturas a até 4,5 metros de você e divida esses Pontos de Vida entre elas.","bonus_ataque":null,"cd":null},{"id":"86a5b9c9-1b62-8e1a-a3b4-24dd74dc217a","revisao_id":"41a5117b-a8be-86ac-a1e2-16467f484e8e","nome_pt":"Traços","tipo":"traco","descricao_pt":"Traços","bonus_ataque":null,"cd":null},{"id":"33f74fa0-d1bd-891d-ae46-6d1405d2568c","revisao_id":"41a5117b-a8be-86ac-a1e2-16467f484e8e","nome_pt":"Anfíbio","tipo":"traco","descricao_pt":"Anfíbio. O dragão pode respirar ar e água.","bonus_ataque":null,"cd":null},{"id":"6a82b12f-232f-8046-ae96-37b449f5ac1a","revisao_id":"41a5117b-a8be-86ac-a1e2-16467f484e8e","nome_pt":"Vínculo Inabalável","tipo":"traco","descricao_pt":"Vínculo Inabalável. Adicione metade do seu Bônus de Proficiência (arredondado para baixo) a qualquer teste de habilidade ou teste de resistência que o dragão fizer.","bonus_ataque":null,"cd":null},{"id":"95c74d74-7710-8c07-acb0-2e5fb5f9cdde","revisao_id":"41a5117b-a8be-86ac-a1e2-16467f484e8e","nome_pt":"Ações","tipo":"traco","descricao_pt":"Ações","bonus_ataque":null,"cd":null},{"id":"6170c8c3-a38f-871a-aedb-d45123b77b88","revisao_id":"41a5117b-a8be-86ac-a1e2-16467f484e8e","nome_pt":"Despedaçar","tipo":"traco","descricao_pt":"Despedaçar. Rolagem de Ataque Corpo a Corpo: +3 + seu modificador de Inteligência, alcance 1,5 m. Acerto: 1d6 + seu modificador de Inteligência de dano de Força.","bonus_ataque":null,"cd":null},{"id":"b00a93f7-05a9-8a27-af29-e99283bdd647","revisao_id":"41a5117b-a8be-86ac-a1e2-16467f484e8e","nome_pt":"Hálito Gravitacional (2/Dia)","tipo":"traco","descricao_pt":"Hálito Gravitacional (2/Dia). Teste de Resistência de Constituição: CD 8 + seu Bônus de Proficiência + seu modificador de Inteligência, cada criatura em um Cone de 4,5 metros. Falha: O alvo é puxado até 4,5 metros em direção ao dragão ou empurrado 4,5 metros para longe (sua escolha).","bonus_ataque":null,"cd":null},{"id":"7dde3e7d-930f-8441-aae4-cbed84b486f5","revisao_id":"1c35ee46-bf7b-8880-a2fa-a28861d52eaa","nome_pt":"Traços","tipo":"traco","descricao_pt":"Traços","bonus_ataque":null,"cd":null},{"id":"5d963b40-c331-8084-a57a-d259f4da2f34","revisao_id":"1c35ee46-bf7b-8880-a2fa-a28861d52eaa","nome_pt":"Vínculo Primitivo","tipo":"traco","descricao_pt":"Vínculo Primitivo. Adicione seu Bônus de Proficiência a qualquer teste de habilidade ou teste de resistência que a besta fizer.","bonus_ataque":null,"cd":null},{"id":"a473ff18-490e-8d91-ac72-ef3cc11cca79","revisao_id":"1c35ee46-bf7b-8880-a2fa-a28861d52eaa","nome_pt":"Ações","tipo":"traco","descricao_pt":"Ações","bonus_ataque":null,"cd":null},{"id":"56163c4e-3e5f-8ae6-a3bd-c1aea52befa9","revisao_id":"1c35ee46-bf7b-8880-a2fa-a28861d52eaa","nome_pt":"Golpe da Besta","tipo":"traco","descricao_pt":"Golpe da Besta. Rolagem de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque de magia, alcance 1,5 m. Acerto: 1d8 + 2 + seu modificador de Sabedoria de dano de Impacto, Perfuração ou Corte (sua escolha ao invocar a besta). Se a besta se moveu pelo menos 6 metros em linha reta em direção ao alvo antes do acerto, o alvo sofre 1d6 extra do mesmo tipo de dano, e o alvo tem a condição Deitado se for uma criatura Grande ou menor.","bonus_ataque":null,"cd":null},{"id":"d50bc5ec-2026-8eff-acac-563cb4208e42","revisao_id":"1cb2bdda-e3c4-8fd0-a7c2-76ca3db912ee","nome_pt":"Traços","tipo":"traco","descricao_pt":"Traços","bonus_ataque":null,"cd":null},{"id":"c6df1789-a29c-86bf-ad85-90217473c93f","revisao_id":"1cb2bdda-e3c4-8fd0-a7c2-76ca3db912ee","nome_pt":"Voo Rápido","tipo":"traco","descricao_pt":"Voo Rápido. A besta não provoca Ataques de Oportunidade quando voa para fora do alcance de um inimigo.","bonus_ataque":null,"cd":null},{"id":"b6f91c4f-8b9a-8141-a3c0-70ba5d478987","revisao_id":"1cb2bdda-e3c4-8fd0-a7c2-76ca3db912ee","nome_pt":"Vínculo Primitivo","tipo":"traco","descricao_pt":"Vínculo Primitivo. Adicione seu Bônus de Proficiência a qualquer teste de habilidade ou teste de resistência que a besta fizer.","bonus_ataque":null,"cd":null},{"id":"01662f68-f1e3-8a5a-ae54-b5f06bd441a8","revisao_id":"1cb2bdda-e3c4-8fd0-a7c2-76ca3db912ee","nome_pt":"Ações","tipo":"traco","descricao_pt":"Ações","bonus_ataque":null,"cd":null},{"id":"8461b069-4905-82c4-a614-2a7783754a11","revisao_id":"1cb2bdda-e3c4-8fd0-a7c2-76ca3db912ee","nome_pt":"Golpe da Besta","tipo":"traco","descricao_pt":"Golpe da Besta. Rolagem de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque de magia, alcance 1,5 m. Acerto: 1d4 + 3 + seu modificador de Sabedoria de dano de Corte.","bonus_ataque":null,"cd":null},{"id":"87ac88bd-554a-80c3-a784-d541450397a1","revisao_id":"3eb85130-7c15-87b9-a856-92fd71bb4271","nome_pt":"Traços","tipo":"traco","descricao_pt":"Traços","bonus_ataque":null,"cd":null},{"id":"1c3bcdde-a55e-8ef9-a882-9b916f0e48cd","revisao_id":"3eb85130-7c15-87b9-a856-92fd71bb4271","nome_pt":"Anfíbio","tipo":"traco","descricao_pt":"Anfíbio. A besta pode respirar ar e água.","bonus_ataque":null,"cd":null},{"id":"4be2c846-7272-8ca1-a651-10e300b5e8bb","revisao_id":"3eb85130-7c15-87b9-a856-92fd71bb4271","nome_pt":"Vínculo Primitivo","tipo":"traco","descricao_pt":"Vínculo Primitivo. Adicione seu Bônus de Proficiência a qualquer teste de habilidade ou teste de resistência que a besta fizer.","bonus_ataque":null,"cd":null},{"id":"7b3f4ed6-3a3b-85d6-a3b8-fc03df8a2c61","revisao_id":"3eb85130-7c15-87b9-a856-92fd71bb4271","nome_pt":"Ações","tipo":"traco","descricao_pt":"Ações","bonus_ataque":null,"cd":null},{"id":"0c735288-e8de-8a33-afc5-638974966f82","revisao_id":"3eb85130-7c15-87b9-a856-92fd71bb4271","nome_pt":"Golpe da Besta","tipo":"traco","descricao_pt":"Golpe da Besta. Rolagem de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque de magia, alcance 1,5 m. Acerto: 1d6 + 2 + seu modificador de Sabedoria de dano de Impacto ou Perfuração (sua escolha ao invocar a besta), e o alvo tem a condição Agarrar (CD de fuga igual à sua CD de resistência de magia).","bonus_ataque":null,"cd":null},{"id":"0e9287f2-b2c8-8d36-a647-8cba0096e4e6","revisao_id":"ad2efd9f-2447-8cd3-a38e-1cb2edfcd868","nome_pt":"Vínculo de Matilha","tipo":"traco","descricao_pt":"Vínculo de Matilha. Adicione seu Bônus de Proficiência a qualquer teste de habilidade ou teste de resistência que a fera fizer.","bonus_ataque":null,"cd":null},{"id":"db37160d-b999-8a9c-abfe-4e1d072cfb9e","revisao_id":"ad2efd9f-2447-8cd3-a38e-1cb2edfcd868","nome_pt":"Mordida","tipo":"acao","descricao_pt":"Mordida. Rolagem de Ataque Corpo a Corpo: Bônus igual ao seu modificador de Constituição mais seu Bônus de Proficiência, alcance 1,5 m. Acerto: 2d4 + 2 mais seu modificador de Constituição. Dano perfurante. Se o alvo for uma criatura Grande ou menor, ele deve ser bem-sucedido em um teste de resistência de Força (CD igual a 8 mais seu modificador de Constituição e Bônus de Proficiência) ou um dos seguintes efeitos à sua escolha ocorrerá: o alvo fica Agarrado, fica Caído ou é empurrado 1,5 m para longe do cão.","bonus_ataque":null,"cd":null}]'::jsonb) e WHERE NOT EXISTS(SELECT 1 FROM public.compendio_criatura_acoes a WHERE a.i