4-fa3e8ec9350e","tabela":10,"linha":4,"coluna":0,"cabecalho_pt":"Nível de Feiticeiro","valor_pt":"9º"},{"id":"4009e850-5811-8306-a059-618996ca1f4c","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":10,"linha":4,"coluna":1,"cabecalho_pt":"Magias Preparadas","valor_pt":"Contatar Outro Plano, Sagrado"},{"id":"0bad3598-cc99-840f-a203-07f346e009c8","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":1,"coluna":0,"cabecalho_pt":"1d6","valor_pt":"1"},{"id":"45bdc861-bd66-8443-aec4-d933218c2deb","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":1,"coluna":1,"cabecalho_pt":"Efeito","valor_pt":"Teias Pegajosas. Teias espessas preenchem a Emanação, tornando-a Terreno Difícil para seus inimigos. Cada inimigo que começa seu turno na Emanação deve ser bem-sucedido em um teste de resistência de Força ou ter a condição Restringido."},{"id":"4792c662-a8c2-8b36-adf1-953c65161152","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":2,"coluna":0,"cabecalho_pt":"1d6","valor_pt":"2"},{"id":"60c3211b-9c6d-8103-a005-c5bbf3e74548","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":2,"coluna":1,"cabecalho_pt":"Efeito","valor_pt":"Gosma Cáustica. Gosma oleosa escorregadia cobre o chão na Emanação, tornando-a Terreno Difícil para inimigos. Cada inimigo que começa seu turno no chão na Emanação sofre 1d6 de dano de Ácido e deve ser bem-sucedido em um teste de resistência de Destreza ou ter a condição Deitado. O dano aumenta em 1d6 nos níveis 11 (2d6) e 16 (3d6)."},{"id":"3b08af9d-aab2-8609-a0a7-971f0064a7b8","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":3,"coluna":0,"cabecalho_pt":"1d6","valor_pt":"3"},{"id":"4dd482c9-5698-852f-ac78-ac42a1156f04","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":3,"coluna":1,"cabecalho_pt":"Efeito","valor_pt":"Gritos Aterrorizantes. Cada inimigo que começa seu turno na Emanação sofre 1d6 de dano Psíquico e deve ser bem-sucedido em um teste de resistência de Sabedoria ou ter a condição Amedrontado até o início de seu próximo turno. O dano aumenta em 1d6 nos níveis 11 (2d6) e 16 (3d6)."},{"id":"827b14e1-250f-8489-aa83-0f19a8d235ab","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":4,"coluna":0,"cabecalho_pt":"1d6","valor_pt":"4"},{"id":"432471d6-a114-87bc-a16e-89573c85b2ec","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":4,"coluna":1,"cabecalho_pt":"Efeito","valor_pt":"Esporos Inebriantes. Esporos intoxicantes preenchem a Emanação, que está Altamente Obscurecida para criaturas de sua escolha. No nível 11, cada inimigo que começa seu turno na Emanação deve ser bem-sucedido em um teste de resistência de Sabedoria ou ter a condição Enfeitiçado até o início de seu próximo turno."},{"id":"b72dd41e-f821-84a9-a877-e148df0b3b83","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":5,"coluna":0,"cabecalho_pt":"1d6","valor_pt":"5"},{"id":"f44fb227-7425-80d6-a598-7c56b963010e","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":5,"coluna":1,"cabecalho_pt":"Efeito","valor_pt":"Folhagem Venenosa. A Emanação está Levemente Obscurecida por flora demoníaca. Cada inimigo que começa seu turno na Emanação sofre 1d6 de dano de Veneno e deve ser bem-sucedido em um teste de resistência de Constituição ou ter a condição Envenenado até o início de seu próximo turno. O dano aumenta em 1d6 nos níveis 11 (2d6) e 16 (3d6)."},{"id":"63be50f9-f1b2-8fc3-a1c6-555bc19d000a","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":6,"coluna":0,"cabecalho_pt":"1d6","valor_pt":"6"},{"id":"cb4ec409-0e08-89cc-a502-8244f3a51e44","revisao_id":"5a32b861-37d4-83d1-a334-fa3e8ec9350e","tabela":11,"linha":6,"coluna":1,"cabecalho_pt":"Efeito","valor_pt":"Ossos Definhantes. Membros espectrais irrompem do chão, alcançando para drenar a vida ao redor. Cada inimigo que começa seu turno na Emanação sofre 1d10 de dano Necrótico e não pode